-- insert-valladolid-centers.sql
-- Inserta los 42 centros de educacion infantil de primer ciclo (0-3 anos)
-- del termino municipal de Valladolid capital investigados y humanizados en este sprint.
-- Fuente primaria: dataset abierto "Directorio de Centros Docentes" de la Junta de
-- Castilla y Leon (analisis.datosabiertos.jcyl.es), filtrado por
-- refine.municipio=VALLADOLID y refine.denominacion_generica en
-- {'ESCUELA DE EDUCACION INFANTIL', 'CENTRO PRIVADO DE EDUCACION INFANTIL'}.
-- Complementado con el listado oficial "Escuelas de Educacion Infantil - Titularidad
-- Junta Castilla y Leon" (educa.jcyl.es), la web oficial del Ayuntamiento de
-- Valladolid (barrio y servicios homogeneos de las 11 Escuelas Infantiles
-- Municipales), el listado oficial de centros adheridos al programa de gratuidad de
-- primer ciclo curso 2026-2027 (educa.jcyl.es) y webs oficiales propias de un
-- subconjunto de centros privados. Ver docs/data-sources-valladolid.md y
-- data/enrichment/valladolid-centers.json.
--
-- Ambito: unicamente el termino municipal de Valladolid capital
-- (refine.municipio=VALLADOLID en la fuente oficial, clasificacion administrativa
-- municipal). No se mezclan otros municipios de la provincia de Valladolid (Laguna
-- de Duero, Arroyo de la Encomienda, Zaratan, Simancas, etc.) aunque aparecieran en
-- la misma fuente provincial/autonomica.
--
-- Ownership: se ha usado 'publico' para los 13 centros de titularidad publica
-- genuina: 2 Escuelas de Educacion Infantil (EEI) de titularidad de la Junta de
-- Castilla y Leon (Amanecer, La Ciguena) y 11 Escuelas Infantiles Municipales (EIM)
-- del Ayuntamiento de Valladolid (La Cometa, El Globo, El Tobogan, Platero, El
-- Principito, Mafalda y Guille, Cascanueces, Fantasia, Campanilla, Caballito Blanco,
-- Cascabel). Los 29 centros privados llevan ownership='privado', nunca
-- 'concertado': el mecanismo de financiacion de Castilla y Leon para el primer
-- ciclo de infantil privado es una subvencion directa a centros adheridos a la
-- oferta gratuita de plazas (Orden EDU/95/2022 y normativa de desarrollo), no un
-- concierto educativo formal. El unico centro del listado oficial con
-- concierto='S' (Santa Catalina) se ha excluido del dataset final por no poder
-- verificar que ese concierto corresponda especificamente al primer ciclo 0-3 anos
-- frente a otras etapas del mismo centro. Ver docs/valladolid-quality-report.md,
-- seccion 1.
--
-- Todos los centros entran con status='draft' (no visibles publicamente por RLS hasta
-- cambiarlos a 'published' manualmente tras auditoria, igual que en Madrid, Barcelona,
-- Valencia, Zaragoza, Murcia, Sevilla, Palma, Malaga, Alicante, Las Palmas, Granada y
-- Cordoba).
-- No toca ningun centro de ninguna otra ciudad ya integrada.
-- No borra ni modifica filas existentes (upsert por slug: si un slug ya existe se
-- actualiza, no se duplica).
-- Generado: 2026-07-12. Revisar antes de ejecutar. NO EJECUTADO POR EL AGENTE.
-- Sin DELETE / DROP / TRUNCATE.

BEGIN;

-- Aseguramos que la ciudad "valladolid" existe antes de insertar sus centros.
INSERT INTO cities (slug, name, province, region)
VALUES ('valladolid', 'Valladolid', 'Valladolid', 'Castilla y Leon')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO centers (
  slug, name, type, ownership, street, postal_code, city_slug, city_name, neighborhood, district, neighborhood_barrio, latitude, longitude, phone, email, website, age_min_months, age_max_months, schedule, services, short_description, long_description, images, faqs, is_claimed, is_verified, social_links, pedagogical_approach, source_url, source_urls_secondary, verified_at, verification_status, confidence_level, data_conflicts, status
)
VALUES
('amanecer-valladolid', 'Amanecer', 'escuela-infantil', 'publico', 'C/ Juana de Castilla, s/n', '47014', 'valladolid', 'Valladolid', NULL, NULL, NULL, 41.65425, -4.73557, '983330369', NULL, 'http://eeiamanecer.centros.educa.jcyl.es/sitio/', 4, 36, NULL, ARRAY['comedor']::text[], 'Amanecer es una escuela infantil de titularidad de la Junta de Castilla y León en C/ Juana de Castilla, s/n, 47014, dentro de la red pública autonómica de primer ciclo de educación infantil (0-3 años) de Valladolid.', 'Amanecer es una escuela infantil de titularidad de la Junta de Castilla y León, con sede en C/ Juana de Castilla, s/n, 47014, Valladolid.

Forma parte de la red de Escuelas de Educación Infantil (EEI) de titularidad autonómica en Castilla y León, que imparte el primer ciclo de educación infantil (0-3 años) con plazas gratuitas para todas las familias desde el curso 2024-2025, dentro del programa de gratuidad del primer ciclo de educación infantil de la Junta de Castilla y León.

Según el registro oficial de centros docentes, el centro ofrece servicio de comedor.

Para conocer el proceso de admisión, unidades disponibles y horario detallado, se recomienda contactar directamente con el centro o consultar el Portal de Educación de la Junta de Castilla y León.', '{}'::text[], '[{"question": "¿Dónde está ubicada la escuela infantil Amanecer?", "answer": "Se encuentra en C/ Juana de Castilla, s/n, 47014, en Valladolid."}, {"question": "¿Qué edades atiende este centro?", "answer": "Es una escuela infantil de primer ciclo de educación infantil, dirigida a niños de 0 a 3 años."}, {"question": "¿Es un centro público o privado?", "answer": "Es un centro de titularidad pública, perteneciente a la red de Escuelas de Educación Infantil de la Junta de Castilla y León."}, {"question": "¿Es gratuita la plaza en este centro?", "answer": "Sí. Desde el curso 2024-2025, Castilla y León ofrece gratuidad total del primer ciclo de educación infantil (0-3 años) en los centros de titularidad de la Junta, dentro del programa de gratuidad de estas enseñanzas."}, {"question": "¿Tiene servicio de comedor?", "answer": "Sí, según el registro oficial de centros docentes de Castilla y León, el centro cuenta con servicio de comedor."}, {"question": "¿Cómo puedo contactar con el centro?", "answer": "Puedes llamar al teléfono 983330369 o consultar su web (http://eeiamanecer.centros.educa.jcyl.es/sitio/)."}]'::jsonb, false, false, '{}'::jsonb, '{}'::text[], 'https://analisis.datosabiertos.jcyl.es/explore/dataset/directorio-de-centros-docentes/', ARRAY['https://www.educa.jcyl.es/es/admision-alumnado/admision-centros-imparten-primer-ciclo-educacion-infantil/listado-escuelas-infantiles-titularidad-jcyl','https://www.educa.jcyl.es/es/admision-alumnado/admision-centros-imparten-primer-ciclo-educacion-infantil/listado-centros-plazas-gratuitas-0-3-anos-curso-2026-2027','http://eeiamanecer.centros.educa.jcyl.es/sitio/']::text[], '2026-07-12'::date, 'unverified', 'high', '{}'::jsonb, 'draft'),
('arbol-sabio-valladolid', 'Árbol Sabio', 'guarderia', 'privado', 'C/ Villafranca de Duero, 4', '47008', 'valladolid', 'Valladolid', NULL, NULL, NULL, 41.61964, -4.75711, '983247742', 'info@arbolsabio.com', 'https://arbolsabio.com/', 4, 36, NULL, ARRAY['cocina-propia','ingles','verano-campamentos']::text[], 'En C/ Villafranca de Duero, 4, 47008, Valladolid, Árbol Sabio atiende a niños de 0 a 3 años dentro del primer ciclo de educación infantil. Es un centro adherido al programa de gratuidad de la Junta de Castilla y León, y su web oficial confirma servicios de cocina propia, inglés y campamentos de verano.', 'Árbol Sabio es un centro privado de educación infantil de primer ciclo (0-3 años), con sede en C/ Villafranca de Duero, 4, 47008, Valladolid.

Según la información publicada en su propia web oficial, el centro ofrece los siguientes servicios confirmados: cocina propia, inglés y campamentos de verano. Estos datos proceden directamente de la web del centro, no de inferencia sobre lo habitual en este tipo de centros.

El centro participa en el programa de gratuidad de las enseñanzas de primer ciclo de educación infantil de la Junta de Castilla y León, que desde el curso 2024-2025 ofrece plazas gratuitas para todas las edades (0 a 3 años) en los centros privados adheridos a esta oferta.

